import log from 'loglevel';
import format from 'loglevel-plugin-browser-prefix';

format(log, 'Theme');

if (window.Shopify?.theme.role === 'development') {
  log.setLevel(log.levels.TRACE, false);
}

export default log;
export const { getLogger } = log;

export function loggerForModule(importMeta) {
  const url = new URL(importMeta.url);
  const moduleName = url
    // Everything after the url
    .pathname
    // Split by directory separator
    .split('/')
    // Get the lasst element
    .slice(-1)[0]
    // Remove build. and .min. from filename
    .replace(/(^build\.|\.min)/g, '');

  return log.getLogger(moduleName);
}
